#!/usr/bin/env bash
# Build OmarchyTV for LG webOS (omarchytv-webos-<appinfo version>-testing.ipk)
# Synchronizes shared fonts, themes, MIT wordmark wallpapers, and tte.js screensaver
# assets from ../launcher/app/src/main/ and generates the binary PNG icons before
# running ares-package.
set -euo pipefail
# The version comes from app/appinfo.json, so the package name never goes stale.
VERSION="$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1]))["version"])' "$(dirname "$0")/app/appinfo.json")"

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"
APP="$SCRIPT_DIR/app"
ANDROID_MAIN="$ROOT/launcher/app/src/main"

mkdir -p "$APP/fonts" "$APP/wallpapers" "$APP/licenses" "$APP/saver"

base64 -d << 'B64_ICON' > "$APP/icon.png"

B64_ICON

base64 -d << 'B64_LARGE' > "$APP/largeIcon.png"

B64_LARGE

base64 -d << 'B64_SPLASH' > "$APP/splash.png"

B64_SPLASH

if [ -d "$ANDROID_MAIN" ]; then
  cp -f "$ANDROID_MAIN/res/font/caskaydia_mono_regular.ttf" "$APP/fonts/"
  cp -f "$ANDROID_MAIN/res/font/caskaydia_mono_bold.ttf" "$APP/fonts/"
  cp -f "$ANDROID_MAIN/assets/omarchy_themes.json" "$APP/omarchy_themes.json"
  cp -rf "$ANDROID_MAIN/assets/wallpapers/"* "$APP/wallpapers/"
  cp -rf "$ANDROID_MAIN/assets/licenses/"* "$APP/licenses/"
  cp -f "$ANDROID_MAIN/assets/saver/tte-bundle.js" "$APP/saver/tte-bundle.js"
  cp -f "$ANDROID_MAIN/assets/saver/screensaver-tv.txt" "$APP/saver/screensaver-tv.txt"
  cp -rf "$ANDROID_MAIN/assets/saver/tte-js" "$APP/saver/"
fi

# Some themes ship their WebP base64-wrapped (a text file starting "UklG", see WallpaperView.java).
# The Android launcher unwraps them in code; a webOS page loads files as they are, so unwrap here.
if base64 -d </dev/null >/dev/null 2>&1; then B64D="base64 -d"; else B64D="base64 -D"; fi   # macOS < 13: -D
for f in "$APP"/wallpapers/*/*.webp; do
  if [ "$(head -c 4 "$f")" = "UklG" ]; then
    $B64D < "$f" > "$f.bin" && mv -f "$f.bin" "$f"
  fi
done

# Rooted-only backend is optional and brings no runtime dependency to the ordinary launcher.
if [ "${OMARCHY_IPHONE_REMOTE:-0}" = 1 ]; then
  npm ci --prefix "$SCRIPT_DIR/iphone-remote" --omit=dev --ignore-scripts
  node "$SCRIPT_DIR/iphone-remote/build.js"
else
  rm -rf "$APP/rooted/iphone-remote"
fi
OUT_DIR="${1:-$SCRIPT_DIR}"
mkdir -p "$OUT_DIR"
ares-package "$APP" -o "$OUT_DIR"
SUFFIX=testing
[ "${OMARCHY_IPHONE_REMOTE:-0}" = 1 ] && SUFFIX=iphone-remote-testing
mv -f "$OUT_DIR/com.omarchytv.home_${VERSION}_all.ipk" "$OUT_DIR/omarchytv-webos-${VERSION}-${SUFFIX}.ipk"
sha256sum "$OUT_DIR/omarchytv-webos-${VERSION}-${SUFFIX}.ipk"
